const V120_VERSION='1.2.0-dev';
const BRAND_V120={
  blue:'#2C3896',orange:'#FF981F',black:'#000000',white:'#FFFFFF',
  icon:'assets/logo-piaget-icon-v152.png',full:'assets/logo-piaget-horizontal-v152.png',seal:'assets/selo-piaget-v152.png'
};

function sanitizeKeyV120(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'')||'padrao'}
function stockIdV120(productId,variationKey='padrao'){return `${sanitizeKeyV120(productId)}__${sanitizeKeyV120(variationKey)}`}
function uniformVariationKeyV120(modelId,size,gender=''){return `${sanitizeKeyV120(modelId)}__${sanitizeKeyV120(size)}__${sanitizeKeyV120(gender||'unico')}`}
function uniformStockIdV120(modelId,size,gender=''){return `farda__${uniformVariationKeyV120(modelId,size,gender)}`}
function stockMapV120(){return new Map((state.inventory||[]).map(x=>[x.id,x]))}
function stockDocV120(productId,variation='padrao'){return stockMapV120().get(stockIdV120(productId,variation))||null}
function uniformStockDocV120(modelId,size,gender=''){return stockMapV120().get(uniformStockIdV120(modelId,size,gender))||null}
function stockAvailableV120(s){return Math.max(0,Number(s?.quantidadeFisica||0)-Number(s?.quantidadeReservada||0))}
function uniformModelByIdV120(id){return (state.uniformModels||[]).find(x=>x.id===id)}
function productControlV120(p){if(!p)return 'sem_controle';if(p.combo)return 'derivado';if(p.id==='salgado'||p.controleCapacidade)return 'capacidade_diaria';return p.controleEstoque||'unitario'}
function isStockConfiguredV120(s){return !!s?.configurado}
function stockStatusTextV120(info){if(info.mode==='sem_controle')return 'Sem controle';if(info.mode==='capacidade_diaria')return `${info.available} disponível(is) hoje`;if(info.mode==='derivado')return info.configured?`${info.available} combinação(ões)`:'Componentes sem estoque';if(!info.configured)return 'Estoque não configurado';return `${info.available} disponível(is)`}
function dailyCapacityInfoV120(){const d=state.dailyCapacity||{},info=typeof lunchDayStatusV181==='function'?lunchDayStatusV181(dateKey(),d):null;if(info)return{planned:info.planned,received:info.received,capacity:info.capacity,used:info.used,available:info.available,deficit:info.deficit,active:info.active,configured:true};const planned=Number(d.quantidadePlanejada??state.config?.quantidadePadraoSalgados??30),used=Number(d.vendidoDinheiro||0)+Number(d.vendidoAvulso||0)+Number(d.consumoConta||0)+Number(d.pedidosConfirmados||0)+activeReservationTotal(d.reservas);return{planned,received:null,capacity:planned,used,available:Math.max(0,planned-used),deficit:Math.max(0,used-planned),active:true,configured:true}}
function productAvailabilityV120(p,seen=new Set()){
  if(!p)return{mode:'sem_controle',configured:true,available:Infinity,sellable:true};
  if(seen.has(p.id))return{mode:'derivado',configured:false,available:0,sellable:false};
  const mode=productControlV120(p);
  if(mode==='sem_controle')return{mode,configured:true,available:Infinity,sellable:true};
  if(mode==='capacidade_diaria'){const d=dailyCapacityInfoV120();return{mode,configured:true,available:d.available,sellable:d.active&&d.available>0,planned:d.planned,received:d.received,capacity:d.capacity,used:d.used,deficit:d.deficit,active:d.active}}
  if(mode==='unitario'){
    const s=stockDocV120(p.id);const configured=isStockConfiguredV120(s),available=configured?stockAvailableV120(s):0;
    return{mode,configured,available,sellable:configured&&available>0,physical:Number(s?.quantidadeFisica||0),reserved:Number(s?.quantidadeReservada||0),stock:s};
  }
  if(mode==='derivado'){
    const next=new Set(seen);next.add(p.id);const comps=(p.componentes||[]).map(c=>{const cp=productById(c.produtoId),i=productAvailabilityV120(cp,next);return{...i,qty:Number(c.quantidade||1),product:cp}});
    if(!comps.length)return{mode,configured:false,available:0,sellable:false,components:[]};
    const configured=comps.every(i=>i.configured!==false),finite=comps.filter(i=>Number.isFinite(i.available));
    const available=finite.length?Math.max(0,Math.floor(Math.min(...finite.map(i=>i.available/i.qty)))):Infinity;
    return{mode,configured,available,sellable:configured&&available>0,components:comps};
  }
  return{mode,configured:true,available:Infinity,sellable:true};
}
function availabilityBadgeV120(info,{uniform=false}={}){
  if(uniform&&info.production)return `<span class="availability-v120 production">Produção necessária</span>`;
  if(info.configured===false)return `<span class="availability-v120 unknown">Não configurado</span>`;
  if(info.available===Infinity)return `<span class="availability-v120 available">Disponível</span>`;
  if(info.available>0)return `<span class="availability-v120 available">${info.available} disponível(is)</span>`;
  return `<span class="availability-v120 unavailable">Sem estoque</span>`;
}
function stockStateBadgeV120(info){
  if(info.mode==='sem_controle')return `<span class="stock-state-v120 unknown">Sem controle</span>`;
  if(info.configured===false)return `<span class="stock-state-v120 unknown">Não configurado</span>`;
  if(info.available<=0)return `<span class="stock-state-v120 zero">Sem estoque</span>`;
  if(info.available<=3)return `<span class="stock-state-v120 low">Estoque baixo</span>`;
  return `<span class="stock-state-v120 ok">Disponível</span>`;
}
function fmtQtyV120(v){return Number(v||0).toLocaleString('pt-BR')}
function statusLabelV120(v){return String(v||'').replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase())}

async function refreshStockStateV120(){
  const [inventory,ds]=await Promise.all([
    typeof window.allCollectionRowsV221==='function'?window.allCollectionRowsV221('estoques',150):db.collection('estoques').get().then(s=>s.docs.map(d=>({id:d.id,...d.data()}))),
    db.collection('disponibilidade_salgados').doc(dateKey()).get()
  ]);
  state.inventory=inventory;
  state.dailyCapacity=ds.exists?ds.data():{dataChave:dateKey(),quantidadePlanejada:Number(state.config?.quantidadePadraoSalgados||30),vendidoDinheiro:0,vendidoAvulso:0,consumoConta:0,pedidosConfirmados:0,reservas:{}};
}

async function migrateV120Schema(){
  const cfgRef=db.collection('configuracoes').doc('sistema');
  const [cfgSnap,pSnap,sSnap,mSnap]=await Promise.all([
    cfgRef.get(),db.collection('produtos').limit(200).get(),db.collection('estoques').limit(500).get().catch(()=>({docs:[]})),db.collection('modelos_farda').limit(100).get().catch(()=>({docs:[]}))
  ]);
  if(cfgSnap.data()?.v120Migrado)return false;
  const existingStocks=new Set(sSnap.docs.map(d=>d.id));
  const existingModels=new Set(mSnap.docs.map(d=>d.id));
  const batch=db.batch(),now=nowIso();
  for(const d of pSnap.docs){
    const p={id:d.id,...d.data()};
    const control=p.combo?'derivado':(p.id==='salgado'||p.controleCapacidade?'capacidade_diaria':(p.controleEstoque||'unitario'));
    batch.set(d.ref,{
      controleEstoque:control,
      vendaCantina:p.vendaCantina??true,
      vendaSecretaria:p.vendaSecretaria??true,
      vendaResponsavel:p.vendaResponsavel??!!p.portal,
      atualizadoEm:now
    },{merge:true});
    if(control==='unitario'){
      const sid=stockIdV120(p.id);if(!existingStocks.has(sid))batch.set(db.collection('estoques').doc(sid),{
        id:sid,produtoId:p.id,tipo:'unitario',variacaoKey:'padrao',configurado:false,quantidadeFisica:0,quantidadeReservada:0,criadoEm:now,atualizadoEm:now
      });
    }
  }
  const modelId='camisa_padrao';
  if(!existingModels.has(modelId))batch.set(db.collection('modelos_farda').doc(modelId),{
    id:modelId,nome:'Camisa de farda',ativo:true,portal:true,
    tamanhosInfantis:['4','6','8','10','12','14'],tamanhosAdultos:['P','M','G','GG','XGG'],
    generoAdulto:true,precoInfantilCentavos:Number(cfgSnap.data()?.precoFardaInfantilCentavos||4200),precoAdultoCentavos:Number(cfgSnap.data()?.precoFardaAdultoCentavos||4700),
    criadoEm:now,atualizadoEm:now
  });
  const variants=[];
  for(const s of ['4','6','8','10','12','14'])variants.push({size:s,gender:''});
  for(const s of ['P','M','G','GG','XGG'])for(const g of ['masculino','feminino'])variants.push({size:s,gender:g});
  for(const v of variants){const sid=uniformStockIdV120(modelId,v.size,v.gender);if(!existingStocks.has(sid))batch.set(db.collection('estoques').doc(sid),{
    id:sid,produtoId:'camisa_farda',tipo:'farda',modeloFardaId:modelId,variacaoKey:uniformVariationKeyV120(modelId,v.size,v.gender),tamanho:v.size,modelo:v.gender,configurado:false,quantidadeFisica:0,quantidadeReservada:0,criadoEm:now,atualizadoEm:now
  })}
  batch.set(cfgRef,{versao:V120_VERSION,v120Migrado:true,precoFardaInfantilCentavos:Number(cfgSnap.data()?.precoFardaInfantilCentavos||4200),precoFardaAdultoCentavos:Number(cfgSnap.data()?.precoFardaAdultoCentavos||4700),atualizadoEm:now},{merge:true});
  await batch.commit();
  return true;
}

async function loadCore(){
  const [as,ps,cs,ss,ms,ds]=await Promise.all([
    db.collection('alunos').get(),db.collection('produtos').limit(200).get(),db.collection('configuracoes').doc('sistema').get(),
    db.collection('estoques').limit(500).get().catch(()=>({docs:[]})),db.collection('modelos_farda').limit(100).get().catch(()=>({docs:[]})),
    db.collection('disponibilidade_salgados').doc(dateKey()).get().catch(()=>({exists:false,data:()=>({})}))
  ]);
  state.students=as.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>a.ordemTurma-b.ordemTurma||a.nome.localeCompare(b.nome));
  state.products=ps.docs.map(d=>({id:d.id,...d.data()}));
  state.config=cs.data();
  state.inventory=ss.docs.map(d=>({id:d.id,...d.data()}));
  state.uniformModels=ms.docs.map(d=>({id:d.id,...d.data()})).filter(x=>x.ativo!==false);
  state.dailyCapacity=ds.exists?ds.data():{dataChave:dateKey(),quantidadePlanejada:Number(state.config?.quantidadePadraoSalgados||30),vendidoDinheiro:0,vendidoAvulso:0,consumoConta:0,pedidosConfirmados:0,reservas:{}};
  if(state.config&&!state.config.v120Migrado){await migrateV120Schema();return loadCore()}
}

