async function renderDashboard(){
  const el=$('#mainContent');el.innerHTML=pageHeader('Resumo','Carregando os indicadores da operação...')+'<div class="empty">Carregando...</div>';
  try{
    await refreshStockStateV120();
    const today=dateKey();
    const [vs,os,accounts,fardas]=await Promise.all([
      db.collection('vendas').where('dataChave','==',today).get(),
      db.collection('ocorrencias_entrega').where('dataChave','==',today).get(),
      typeof window.loadAllFinancialAccountsV221==='function'?window.loadAllFinancialAccountsV221():db.collection('contas_responsaveis').get().then(s=>s.docs.map(d=>({id:d.id,...d.data()}))),
      typeof window.allCollectionRowsV221==='function'?window.allCollectionRowsV221('pedidos_farda',100):db.collection('pedidos_farda').get().then(s=>s.docs.map(d=>({id:d.id,...d.data()})))
    ]);
    const salesAll=vs.docs.map(d=>({id:d.id,...d.data()})),sales=salesAll.filter(x=>!String(x.status||'').toLowerCase().includes('cancel')),occ=os.docs.map(d=>d.data());
    const gross=sales.reduce((sum,x)=>sum+Number(x.valorBrutoCentavos||0),0),debt=accounts.reduce((sum,x)=>sum+Number(x.dividaCentavos||0),0),blocked=accounts.filter(x=>x.bloqueadoPorLimite||x.bloqueioManual).length,pendingUniform=fardas.filter(x=>!['entregue','cancelado'].includes(x.statusAtendimento)).length;
    const stockAlerts=(state.products||[]).filter(p=>p.ativo&&!p.combo&&productControlV120(p)==='unitario').filter(p=>{const i=productAvailabilityV120(p);return i.configured===false||i.available<=3}).length;
    el.innerHTML=pageHeader('Resumo','Modo de contingência: indicadores recalculados diretamente na base.',state.user?.perfil!=='cantina'?`<button class="btn btn-primary" onclick="navigate('vendas');setTimeout(startSaleWizardV120,120)">+ Iniciar venda</button>`:'')+`
    <div class="alert warn" style="margin-bottom:14px">O resumo incremental não estava disponível e o sistema realizou a leitura completa necessária para preservar a integridade dos indicadores.</div>
    <div class="grid g4">
      <div class="kpi clickable" onclick="renderInsightV110('sales')"><div class="kpi-label">Vendas hoje</div><div class="kpi-value">${fmt(gross)}</div><div class="kpi-sub">${sales.length} operações registradas</div><span class="kpi-arrow">›</span></div>
      <div class="kpi orange clickable" onclick="renderInsightV110('debts')"><div class="kpi-label">Valores em aberto</div><div class="kpi-value">${fmt(debt)}</div><div class="kpi-sub">${accounts.filter(x=>Number(x.dividaCentavos||0)>0).length} contas familiares</div><span class="kpi-arrow">›</span></div>
      <div class="kpi red clickable" onclick="renderInsightV110('blocked')"><div class="kpi-label">Contas bloqueadas</div><div class="kpi-value">${blocked}</div><div class="kpi-sub">Limite ou bloqueio manual</div><span class="kpi-arrow">›</span></div>
      <div class="kpi green clickable" onclick="renderProdutos('estoque')"><div class="kpi-label">Atenção no estoque</div><div class="kpi-value">${stockAlerts}</div><div class="kpi-sub">Baixo, zerado ou não configurado</div><span class="kpi-arrow">›</span></div>
    </div>
    <div class="grid g2" style="margin-top:14px">
      <div class="card clickable" onclick="renderInsightV110('deliveries')"><div class="card-head"><div class="card-title">Entregas de hoje</div><span class="badge b-blue">ver detalhes</span></div><div class="card-body"><div class="kpi-value">${occ.filter(x=>x.status==='programado').length}</div><span class="muted">programadas</span> · <strong>${occ.filter(x=>x.status==='entregue').length}</strong> entregues · <strong>${occ.filter(x=>x.status==='ausente').length}</strong> ausências</div></div>
      <div class="card clickable" onclick="renderInsightV110('uniforms')"><div class="card-head"><div class="card-title">Fardas pendentes</div><span class="badge b-blue">ver pedidos</span></div><div class="card-body"><div class="kpi-value">${pendingUniform}</div><span class="muted">produção, reserva ou entrega</span></div></div>
    </div>`;
  }catch(e){console.warn('dashboard-fallback-v221',e);el.innerHTML=pageHeader('Resumo','Falha ao carregar indicadores.')+`<div class="alert danger">${esc(e.message||'Falha de leitura')}. <button class="btn btn-light" onclick="renderDashboard()">Tentar novamente</button></div>`}
}

/* =========================
   Estoque central — helpers transacionais
   ========================= */
function groupCatalogItemsV120(items){
  const map=new Map();for(const x of items||[]){if(!x.produtoId)continue;const q=Number(x.quantidade||1);if(q<=0)continue;const g=map.get(x.produtoId)||{produtoId:x.produtoId,quantidade:0,nome:x.nome||productById(x.produtoId)?.nome||x.produtoId};g.quantidade+=q;map.set(x.produtoId,g)}return[...map.values()]
}
async function planCatalogInventoryTxV120(tx,items,meta={}){
  const groups=groupCatalogItemsV120(items),unitPlans=[];let salgadoQty=0;
  for(const g of groups){
    const p=productById(g.produtoId);if(!p)continue;const mode=productControlV120(p);
    if(mode==='unitario'){
      const ref=db.collection('estoques').doc(stockIdV120(p.id)),snap=await tx.get(ref),d=snap.exists?snap.data():null;
      if(!d?.configurado)throw new Error(`O estoque de ${p.nome} ainda não foi configurado.`);
      const available=stockAvailableV120(d);if(available<g.quantidade)throw new Error(`Estoque insuficiente de ${p.nome}. Disponível: ${available}.`);
      unitPlans.push({ref,data:d,product:p,qty:g.quantidade});
    }else if(mode==='capacidade_diaria')salgadoQty+=g.quantidade;
  }
  let salgadoPlan=null;if(salgadoQty>0)salgadoPlan=await readSalgadoUpdateTx(tx,[{produtoId:'salgado',quantidade:salgadoQty}],meta.salgadoKind||'venda_secretaria');
  return{unitPlans,salgadoPlan,salgadoQty,meta};
}
function writeCatalogInventoryPlanV120(tx,plan){
  for(const pl of plan.unitPlans){const mov=db.collection('movimentos_estoque').doc(),newPhysical=Number(pl.data.quantidadeFisica||0)-pl.qty;tx.set(pl.ref,{quantidadeFisica:newPhysical,atualizadoEm:nowIso(),ultimoMovimentoEm:nowIso()},{merge:true});tx.set(mov,{id:mov.id,produtoId:pl.product.id,tipo:'saida_venda',quantidade:-pl.qty,origem:plan.meta.origem||'sistema',sourceId:plan.meta.sourceId||null,alunoId:plan.meta.alunoId||null,usuarioId:state.user?.id||null,dataChave:dateKey(),criadoEm:nowIso()})}
  if(plan.salgadoPlan){tx.set(plan.salgadoPlan.ref,plan.salgadoPlan.data,{merge:true});const mov=db.collection('movimentos_estoque').doc();tx.set(mov,{id:mov.id,produtoId:'salgado',tipo:'saida_venda',quantidade:-plan.salgadoQty,origem:plan.meta.origem||'sistema',sourceId:plan.meta.sourceId||null,alunoId:plan.meta.alunoId||null,usuarioId:state.user?.id||null,dataChave:dateKey(),criadoEm:nowIso()})}
}
async function applyCatalogInventoryTxV120(tx,items,meta={}){const plan=await planCatalogInventoryTxV120(tx,items,meta);writeCatalogInventoryPlanV120(tx,plan)}

async function planUniformInventoryTxV120(tx,items,meta={}){
  const plans=[];
  for(const x of items||[]){
    const action=x.estoqueAcao||((x.statusAtendimento==='entregue')?'saida_imediata':(x.statusAtendimento==='reservado_estoque'?'reservar':'producao'));if(action==='producao')continue;
    const modelId=x.modeloFardaId||'camisa_padrao',ref=db.collection('estoques').doc(uniformStockIdV120(modelId,x.tamanho,x.modelo||'')),snap=await tx.get(ref),d=snap.exists?snap.data():null;
    if(!d?.configurado)throw new Error(`O estoque da farda ${x.tamanho}${x.modelo?` ${x.modelo}`:''} ainda não foi configurado.`);
    const available=stockAvailableV120(d),q=Number(x.quantidade||1);if(available<q)throw new Error(`Não há farda suficiente para ${x.tamanho}${x.modelo?` ${x.modelo}`:''}. Disponível: ${available}.`);
    plans.push({x,action,ref,d,q,modelId});
  }
  return{plans,meta};
}
function writeUniformInventoryPlanV120(tx,plan){
  for(const pl of plan.plans){const mov=db.collection('movimentos_estoque').doc();if(pl.action==='reservar'){tx.set(pl.ref,{quantidadeReservada:Number(pl.d.quantidadeReservada||0)+pl.q,atualizadoEm:nowIso(),ultimoMovimentoEm:nowIso()},{merge:true});tx.set(mov,{id:mov.id,produtoId:'camisa_farda',modeloFardaId:pl.modelId,variacaoKey:pl.d.variacaoKey,tamanho:pl.x.tamanho,modelo:pl.x.modelo||'',tipo:'reserva',quantidade:pl.q,origem:plan.meta.origem||'secretaria',sourceId:plan.meta.sourceId||null,alunoId:plan.meta.alunoId||null,usuarioId:state.user?.id||null,dataChave:dateKey(),criadoEm:nowIso()})}else{tx.set(pl.ref,{quantidadeFisica:Number(pl.d.quantidadeFisica||0)-pl.q,atualizadoEm:nowIso(),ultimoMovimentoEm:nowIso()},{merge:true});tx.set(mov,{id:mov.id,produtoId:'camisa_farda',modeloFardaId:pl.modelId,variacaoKey:pl.d.variacaoKey,tamanho:pl.x.tamanho,modelo:pl.x.modelo||'',tipo:'saida_venda',quantidade:-pl.q,origem:plan.meta.origem||'secretaria',sourceId:plan.meta.sourceId||null,alunoId:plan.meta.alunoId||null,usuarioId:state.user?.id||null,dataChave:dateKey(),criadoEm:nowIso()})}}
}
async function applyUniformInventoryTxV120(tx,items,meta={}){const plan=await planUniformInventoryTxV120(tx,items,meta);writeUniformInventoryPlanV120(tx,plan)}

