async function renderStockMovementsV120(){const h=$('#productsWorkspaceV120'),s=await db.collection('movimentos_estoque').orderBy('criadoEm','desc').limit(120).get(),rows=s.docs.map(d=>({id:d.id,...d.data()}));h.innerHTML=`<div class="card"><div class="card-head"><div class="card-title">Últimas movimentações</div><span class="muted">${rows.length} registro(s)</span></div>${rows.length?`<div class="table-wrap" style="border:0"><table><thead><tr><th>Data</th><th>Produto</th><th>Tipo</th><th>Origem</th><th style="text-align:right">Quantidade</th></tr></thead><tbody>${rows.map(r=>{const p=productById(r.produtoId),name=r.produtoId==='camisa_farda'?(uniformModelByIdV120(r.modeloFardaId)?.nome||'Farda'):p?.nome||r.produtoId;return `<tr><td>${humanDate(r.criadoEm)}</td><td><strong>${esc(name)}</strong>${r.tamanho?`<br><span class="muted">${esc(r.tamanho)} ${esc(r.modelo||'')}</span>`:''}</td><td>${esc(statusLabelV120(r.tipo))}</td><td>${esc(statusLabelV120(r.origem||'-'))}</td><td class="money ${Number(r.quantidade||0)>=0?'inventory-movement-positive':'inventory-movement-negative'}">${Number(r.quantidade||0)>0?'+':''}${fmtQtyV120(r.quantidade)}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma movimentação registrada.</div>'}</div>`}
function renderReplenishmentV120(){const h=$('#productsWorkspaceV120'),unit=state.products.filter(p=>p.ativo&&productControlV120(p)==='unitario');h.innerHTML=`<div class="grid g2"><div class="card"><div class="card-head"><div class="card-title">Registrar entrada</div></div><div class="card-body"><div class="fg"><label>Produto</label><select id="replenishProductV120" class="fi">${unit.map(p=>`<option value="${p.id}">${esc(p.nome)}</option>`).join('')}</select></div><div class="fg"><label>Quantidade recebida</label><input id="replenishQtyV120" type="number" min="1" class="fi" placeholder="0"></div><div class="fg"><label>Observação</label><input id="replenishNoteV120" class="fi" placeholder="Ex.: reposição semanal"></div><button class="btn btn-primary" style="width:100%" onclick="saveReplenishmentV120()">Confirmar entrada</button></div></div><div class="card"><div class="card-head"><div class="card-title">Como funciona</div></div><div class="card-body"><div class="alert">Entradas, vendas, reservas, liberações e ajustes ficam registradas individualmente. O sistema não armazena custo ou margem do fornecedor.</div><p class="muted" style="line-height:1.6">Produtos ainda não configurados precisam receber um estoque inicial antes da primeira venda. O salgado continua com capacidade diária. Combos consomem os componentes.</p></div></div></div>`}
function renderUniformModelsV120(){const h=$('#productsWorkspaceV120'),models=state.uniformModels||[];h.innerHTML=`<div class="stock-toolbar-v120"><div><strong>Modelos cadastrados</strong><div class="muted">Cada modelo pode ter preços e variações próprias.</div></div><button class="btn btn-primary" onclick="openNewUniformModelV120()">+ Novo modelo</button></div><div class="catalog-list-v120">${models.map(m=>`<div class="catalog-card-v120"><div><strong>${esc(m.nome)}</strong><div class="meta">4–14: ${fmt(m.precoInfantilCentavos)} · Adultos: ${fmt(m.precoAdultoCentavos)}</div><div style="margin-top:7px"><span class="badge ${m.ativo!==false?'b-green':'b-red'}">${m.ativo!==false?'ativo':'inativo'}</span> <span class="badge b-blue">${m.portal!==false?'portal':'interno'}</span></div></div><div class="actions"><button class="btn btn-light" onclick="editUniformModelV120('${m.id}')">Editar</button><button class="btn btn-outline" onclick="renderProdutos('estoque')">Estoque</button></div></div>`).join('')||'<div class="empty">Nenhum modelo.</div>'}</div>`}
function openNewProductV120(){openModal('Novo produto',productFormV120())}
function productFormV120(p={}){return `<div class="form-row"><div class="fg"><label>Nome</label><input id="prodNameV120" class="fi" value="${esc(p.nome||'')}"></div><div class="fg"><label>Categoria</label><input id="prodCatV120" class="fi" value="${esc(p.categoria||'')}"></div></div><div class="form-row"><div class="fg"><label>Preço</label><input id="prodPriceV120" class="fi" value="${p.precoCentavos!=null?(Number(p.precoCentavos)/100).toFixed(2).replace('.',','):''}" placeholder="0,00"></div><div class="fg"><label>Controle</label><select id="prodControlV120" class="fi"><option value="unitario" ${productControlV120(p)==='unitario'?'selected':''}>Estoque unitário</option><option value="sem_controle" ${productControlV120(p)==='sem_controle'?'selected':''}>Sem controle de estoque</option></select></div></div><div class="grid g3"><label class="switch-line"><span><strong>Cantina</strong><small class="muted">Pode vender</small></span><input id="prodCantinaV120" type="checkbox" ${p.vendaCantina!==false?'checked':''}></label><label class="switch-line"><span><strong>Secretaria</strong><small class="muted">Pode vender</small></span><input id="prodSecretariaV120" type="checkbox" ${p.vendaSecretaria!==false?'checked':''}></label><label class="switch-line"><span><strong>Responsável</strong><small class="muted">Aparece no portal</small></span><input id="prodPortalV120" type="checkbox" ${(p.vendaResponsavel??p.portal)?'checked':''}></label></div><button class="btn btn-primary" style="width:100%;margin-top:15px" onclick="${p.id?`saveProductEditV120('${p.id}')`:'saveNewProductV120()'}">Salvar produto</button>`}
async function saveNewProductV120(){const name=$('#prodNameV120').value.trim(),cat=$('#prodCatV120').value.trim(),price=parseBRL($('#prodPriceV120').value),control=$('#prodControlV120').value;if(!name||!cat||price<=0)return appMessage('Preencha nome, categoria e preço.');const id=`produto_${sanitizeKeyV120(name)}_${Date.now().toString(36)}`,ref=db.collection('produtos').doc(id),now=nowIso(),batch=db.batch();batch.set(ref,{id,nome:name,categoria:cat,precoCentavos:price,ativo:true,vendaRapida:false,portal:$('#prodPortalV120').checked,vendaResponsavel:$('#prodPortalV120').checked,vendaCantina:$('#prodCantinaV120').checked,vendaSecretaria:$('#prodSecretariaV120').checked,controleEstoque:control,combo:false,criadoEm:now,atualizadoEm:now});if(control==='unitario'){const sid=stockIdV120(id);batch.set(db.collection('estoques').doc(sid),{id:sid,produtoId:id,tipo:'unitario',variacaoKey:'padrao',configurado:false,quantidadeFisica:0,quantidadeReservada:0,criadoEm:now,atualizadoEm:now})}await batch.commit();await audit('produto_criado',{produtoId:id});await loadCore();closeModal();renderProdutos('catalogo');toast('Produto cadastrado.')}
function editProductV120(id){const p=productById(id);if(!p)return;openModal('Editar produto',productFormV120(p)+`<div class="actions" style="margin-top:12px"><button class="btn ${p.ativo?'btn-red':'btn-green'}" onclick="toggleProductV120('${id}',${!p.ativo})">${p.ativo?'Inativar':'Ativar'}</button></div>`)}
async function saveProductEditV120(id){const p=productById(id),price=parseBRL($('#prodPriceV120').value),control=$('#prodControlV120').value;if(!$('#prodNameV120').value.trim()||!$('#prodCatV120').value.trim()||price<=0)return appMessage('Preencha os campos corretamente.');const batch=db.batch(),now=nowIso();batch.set(db.collection('produtos').doc(id),{nome:$('#prodNameV120').value.trim(),categoria:$('#prodCatV120').value.trim(),precoCentavos:price,controleEstoque:control,portal:$('#prodPortalV120').checked,vendaResponsavel:$('#prodPortalV120').checked,vendaCantina:$('#prodCantinaV120').checked,vendaSecretaria:$('#prodSecretariaV120').checked,historicoPrecos:[...(p.historicoPrecos||[]),...(price!==Number(p.precoCentavos||0)?[{precoCentavos:price,inicioEm:now,usuario:state.user.id}]:[])],atualizadoEm:now},{merge:true});if(control==='unitario'&&!stockDocV120(id)){const sid=stockIdV120(id);batch.set(db.collection('estoques').doc(sid),{id:sid,produtoId:id,tipo:'unitario',variacaoKey:'padrao',configurado:false,quantidadeFisica:0,quantidadeReservada:0,criadoEm:now,atualizadoEm:now})}await batch.commit();await audit('produto_editado',{produtoId:id});await loadCore();closeModal();renderProdutos('catalogo');toast('Produto atualizado.')}
async function toggleProductV120(id,val){await db.collection('produtos').doc(id).set({ativo:val,atualizadoEm:nowIso()},{merge:true});await audit(val?'produto_ativado':'produto_inativado',{produtoId:id});await loadCore();closeModal();renderProdutos('catalogo')}
function openStockEntryV120(productId){const s=stockDocV120(productId),p=productById(productId);if(!p)return;openModal(s?.configurado?'Movimentar estoque':'Definir estoque inicial',`<p><strong>${esc(p.nome)}</strong></p>${s?.configurado?`<div class="grid g3"><div class="kpi"><div class="kpi-label">Físico</div><div class="kpi-value">${fmtQtyV120(s.quantidadeFisica)}</div></div><div class="kpi orange"><div class="kpi-label">Reservado</div><div class="kpi-value">${fmtQtyV120(s.quantidadeReservada)}</div></div><div class="kpi green"><div class="kpi-label">Disponível</div><div class="kpi-value">${fmtQtyV120(stockAvailableV120(s))}</div></div></div>`:''}<div class="fg" style="margin-top:14px"><label>${s?.configurado?'Tipo de movimento':'Quantidade física atual'}</label>${s?.configurado?`<select id="stockActionV120" class="fi"><option value="entrada">Entrada / reposição</option><option value="saida_ajuste">Baixa por ajuste</option><option value="definir">Corrigir saldo físico para</option></select>`:''}<input id="stockQtyV120" type="number" min="0" class="fi" placeholder="0" style="margin-top:8px"></div><div class="fg"><label>Observação</label><input id="stockNoteV120" class="fi" placeholder="Motivo ou referência"></div><button class="btn btn-primary" style="width:100%" onclick="saveStockMovementV120('${stockIdV120(productId)}')">Salvar</button>`)}
function openStockEntryByIdV120(stockId){const s=stockMapV120().get(stockId);if(!s)return;const name=s.tipo==='farda'?(uniformModelByIdV120(s.modeloFardaId)?.nome||'Farda'):productById(s.produtoId)?.nome||s.produtoId;openModal(s.configurado?'Movimentar estoque':'Definir estoque inicial',`<p><strong>${esc(name)}</strong>${s.tamanho?` — ${esc(s.tamanho)} ${esc(s.modelo||'')}`:''}</p>${s.configurado?`<div class="grid g3"><div class="kpi"><div class="kpi-label">Físico</div><div class="kpi-value">${fmtQtyV120(s.quantidadeFisica)}</div></div><div class="kpi orange"><div class="kpi-label">Reservado</div><div class="kpi-value">${fmtQtyV120(s.quantidadeReservada)}</div></div><div class="kpi green"><div class="kpi-label">Disponível</div><div class="kpi-value">${fmtQtyV120(stockAvailableV120(s))}</div></div></div>`:''}<div class="fg" style="margin-top:14px"><label>${s.configurado?'Tipo de movimento':'Quantidade física atual'}</label>${s.configurado?`<select id="stockActionV120" class="fi"><option value="entrada">Entrada / reposição</option><option value="saida_ajuste">Baixa por ajuste</option><option value="definir">Corrigir saldo físico para</option></select>`:''}<input id="stockQtyV120" type="number" min="0" class="fi" placeholder="0" style="margin-top:8px"></div><div class="fg"><label>Observação</label><input id="stockNoteV120" class="fi" placeholder="Motivo ou referência"></div><button class="btn btn-primary" style="width:100%" onclick="saveStockMovementV120('${stockId}')">Salvar</button>`)}
async function saveStockMovementV120(stockId){const qty=Number($('#stockQtyV120').value);if(!Number.isFinite(qty)||qty<0)return appMessage('Quantidade inválida.');const ref=db.collection('estoques').doc(stockId),mov=db.collection('movimentos_estoque').doc();await db.runTransaction(async tx=>{const snap=await tx.get(ref),s=snap.data()||{};const configured=!!s.configurado,action=configured?($('#stockActionV120')?.value||'entrada'):'definir',current=Number(s.quantidadeFisica||0);let next=current,delta=0,type='ajuste_inicial';if(!configured||action==='definir'){next=qty;delta=qty-current;type=configured?'ajuste_saldo':'estoque_inicial'}else if(action==='entrada'){next=current+qty;delta=qty;type='entrada'}else{if(current-qty<Number(s.quantidadeReservada||0))throw new Error('A baixa deixaria o estoque físico abaixo do que já está reservado.');next=current-qty;delta=-qty;type='saida_ajuste'}tx.set(ref,{configurado:true,quantidadeFisica:next,atualizadoEm:nowIso(),ultimoMovimentoEm:nowIso()},{merge:true});tx.set(mov,{id:mov.id,produtoId:s.produtoId||null,modeloFardaId:s.modeloFardaId||null,variacaoKey:s.variacaoKey||null,tamanho:s.tamanho||null,modelo:s.modelo||null,tipo:type,quantidade:delta,origem:'ajuste_manual',observacao:$('#stockNoteV120')?.value||'',usuarioId:state.user.id,dataChave:dateKey(),criadoEm:nowIso()})});await audit('movimento_estoque',{stockId});await refreshStockStateV120();closeModal();renderProdutos(state.productsTabV120||'estoque');toast('Estoque atualizado.')}
async function saveReplenishmentV120(){const id=$('#replenishProductV120').value,qty=Number($('#replenishQtyV120').value);if(!id||!Number.isFinite(qty)||qty<=0)return appMessage('Informe uma quantidade válida.');const s=stockDocV120(id);if(!s?.configurado)return appMessage('Defina primeiro o estoque inicial deste produto.');const ref=db.collection('estoques').doc(s.id),mov=db.collection('movimentos_estoque').doc();await db.runTransaction(async tx=>{const snap=await tx.get(ref),d=snap.data();tx.set(ref,{quantidadeFisica:Number(d.quantidadeFisica||0)+qty,atualizadoEm:nowIso(),ultimoMovimentoEm:nowIso()},{merge:true});tx.set(mov,{id:mov.id,produtoId:id,tipo:'entrada',quantidade:qty,origem:'reposicao',observacao:$('#replenishNoteV120').value||'',usuarioId:state.user.id,dataChave:dateKey(),criadoEm:nowIso()})});await audit('estoque_reposicao_registrada',{produtoId:id,estoqueId:s.id,quantidade:qty,movimentoEstoqueId:mov.id,observacao:$('#replenishNoteV120').value||''});await refreshStockStateV120();renderProdutos('reposicao');toast('Reposição registrada.')}
function openDailyCapacityV120(){const d=dailyCapacityInfoV120();openModal('Capacidade de salgados — hoje',`<div class="grid g3"><div class="kpi"><div class="kpi-label">Planejado</div><div class="kpi-value">${d.planned}</div></div><div class="kpi orange"><div class="kpi-label">Utilizado</div><div class="kpi-value">${d.used}</div></div><div class="kpi green"><div class="kpi-label">Disponível</div><div class="kpi-value">${d.available}</div></div></div><div class="fg" style="margin-top:14px"><label>Quantidade planejada / recebida hoje</label><input id="dailyCapV120" type="number" min="0" class="fi" value="${d.planned}"></div><button class="btn btn-primary" style="width:100%" onclick="saveDailyCapacityV120()">Salvar quantidade do dia</button>`)}
async function saveDailyCapacityV120(){const q=Number($('#dailyCapV120').value);if(!Number.isFinite(q)||q<0)return appMessage('Quantidade inválida.');const d=dailyCapacityInfoV120();if(q<d.used)return appMessage(`Não é possível definir abaixo do que já foi utilizado (${d.used}).`);await db.collection('disponibilidade_salgados').doc(dateKey()).set({dataChave:dateKey(),quantidadePlanejada:q,atualizadoEm:nowIso()},{merge:true});await audit('capacidade_lanches_atualizada',{dataChave:dateKey(),quantidadePlanejada:q,quantidadeComprometida:d.used});await refreshStockStateV120();closeModal();renderProdutos('estoque');toast('Capacidade do dia atualizada.')}
function uniformModelFormV120(m={}){return `<div class="fg"><label>Nome do modelo</label><input id="uniformModelNameV120" class="fi" value="${esc(m.nome||'')}"></div><div class="form-row"><div class="fg"><label>Preço 4 a 14</label><input id="uniformModelChildPriceV120" class="fi" value="${m.precoInfantilCentavos!=null?(m.precoInfantilCentavos/100).toFixed(2).replace('.',','):'42,00'}"></div><div class="fg"><label>Preço P a XGG</label><input id="uniformModelAdultPriceV120" class="fi" value="${m.precoAdultoCentavos!=null?(m.precoAdultoCentavos/100).toFixed(2).replace('.',','):'47,00'}"></div></div><div class="form-row"><div class="fg"><label>Tamanhos infantis</label><input id="uniformModelChildSizesV120" class="fi" value="${esc((m.tamanhosInfantis||['4','6','8','10','12','14']).join(', '))}"></div><div class="fg"><label>Tamanhos adultos</label><input id="uniformModelAdultSizesV120" class="fi" value="${esc((m.tamanhosAdultos||['P','M','G','GG','XGG']).join(', '))}"></div></div><label class="switch-line"><span><strong>Variação masculino/feminino nos adultos</strong></span><input id="uniformModelGenderV120" type="checkbox" ${m.generoAdulto!==false?'checked':''}></label><label class="switch-line" style="margin-top:10px"><span><strong>Disponível para o responsável</strong></span><input id="uniformModelPortalV120" type="checkbox" ${m.portal!==false?'checked':''}></label><button class="btn btn-primary" style="width:100%;margin-top:14px" onclick="${m.id?`saveUniformModelEditV120('${m.id}')`:'saveNewUniformModelV120()'}">Salvar modelo</button>`}
function openNewUniformModelV120(){openModal('Novo modelo de farda',uniformModelFormV120())}
function editUniformModelV120(id){const m=uniformModelByIdV120(id);openModal('Editar modelo de farda',uniformModelFormV120(m))}
function parseSizesV120(v){return String(v||'').split(',').map(x=>x.trim()).filter(Boolean)}
async function saveNewUniformModelV120(){const name=$('#uniformModelNameV120').value.trim(),child=parseBRL($('#uniformModelChildPriceV120').value),adult=parseBRL($('#uniformModelAdultPriceV120').value),cs=parseSizesV120($('#uniformModelChildSizesV120').value),as=parseSizesV120($('#uniformModelAdultSizesV120').value);if(!name||child<=0||adult<=0||!cs.length)return appMessage('Preencha o modelo e os preços.');const id=`farda_${sanitizeKeyV120(name)}_${Date.now().toString(36)}`,now=nowIso(),gender=$('#uniformModelGenderV120').checked,batch=db.batch();batch.set(db.collection('modelos_farda').doc(id),{id,nome:name,ativo:true,portal:$('#uniformModelPortalV120').checked,tamanhosInfantis:cs,tamanhosAdultos:as,generoAdulto:gender,precoInfantilCentavos:child,precoAdultoCentavos:adult,criadoEm:now,atualizadoEm:now});const vars=[...cs.map(size=>({size,gender:''})),...as.flatMap(size=>gender?[{size,gender:'masculino'},{size,gender:'feminino'}]:[{size,gender:''}])];for(const v of vars){const sid=uniformStockIdV120(id,v.size,v.gender);batch.set(db.collection('estoques').doc(sid),{id:sid,produtoId:'camisa_farda',tipo:'farda',modeloFardaId:id,variacaoKey:uniformVariationKeyV120(id,v.size,v.gender),tamanho:v.size,modelo:v.gender,configurado:false,quantidadeFisica:0,quantidadeReservada:0,criadoEm:now,atualizadoEm:now})}await batch.commit();await audit('modelo_farda_criado',{modeloFardaId:id,nome:name,precoInfantilCentavos:child,precoAdultoCentavos:adult,portal:$('#uniformModelPortalV120').checked});await loadCore();closeModal();renderProdutos('fardas');toast('Modelo criado. Agora defina o estoque das variações.')}
async function saveUniformModelEditV120(id){const name=$('#uniformModelNameV120').value.trim(),child=parseBRL($('#uniformModelChildPriceV120').value),adult=parseBRL($('#uniformModelAdultPriceV120').value),cs=parseSizesV120($('#uniformModelChildSizesV120').value),as=parseSizesV120($('#uniformModelAdultSizesV120').value),gender=$('#uniformModelGenderV120').checked;if(!name||child<=0||adult<=0)return appMessage('Dados inválidos.');const batch=db.batch(),now=nowIso();batch.set(db.collection('modelos_farda').doc(id),{nome:name,portal:$('#uniformModelPortalV120').checked,tamanhosInfantis:cs,tamanhosAdultos:as,generoAdulto:gender,precoInfantilCentavos:child,precoAdultoCentavos:adult,atualizadoEm:now},{merge:true});const existing=new Set((state.inventory||[]).filter(x=>x.tipo==='farda'&&x.modeloFardaId===id).map(x=>x.id)),vars=[...cs.map(size=>({size,gender:''})),...as.flatMap(size=>gender?[{size,gender:'masculino'},{size,gender:'feminino'}]:[{size,gender:''}])];for(const v of vars){const sid=uniformStockIdV120(id,v.size,v.gender);if(!existing.has(sid))batch.set(db.collection('estoques').doc(sid),{id:sid,produtoId:'camisa_farda',tipo:'farda',modeloFardaId:id,variacaoKey:uniformVariationKeyV120(id,v.size,v.gender),tamanho:v.size,modelo:v.gender,configurado:false,quantidadeFisica:0,quantidadeReservada:0,criadoEm:now,atualizadoEm:now})}await batch.commit();await audit('modelo_farda_atualizado',{modeloFardaId:id,nome:name,precoInfantilCentavos:child,precoAdultoCentavos:adult,portal:$('#uniformModelPortalV120').checked});await loadCore();closeModal();renderProdutos('fardas');toast('Modelo atualizado.')}

