async function renderFardas(){try{await refreshStockStateV120();const raw=typeof window.allCollectionRowsV221==='function'?await window.allCollectionRowsV221('pedidos_farda',100):await db.collection('pedidos_farda').get().then(s=>s.docs.map(d=>({id:d.id,...d.data()})));const rows=raw.sort((a,b)=>String(b.criadoEm).localeCompare(String(a.criadoEm))),prod=rows.filter(x=>['aguardando_producao','enviado_fabrica','em_producao'].includes(x.statusAtendimento)).length,ready=rows.filter(x=>x.statusAtendimento==='pronto_retirada').length;$('#mainContent').innerHTML=pageHeader('Fardas','Estoque por variação, produção e entrega.',`<div class="actions"><button class="btn btn-outline" onclick="renderProdutos('estoque')">Ver estoque</button><button class="btn btn-primary" onclick="newUniformOrder()">+ Novo pedido</button></div>`)+`<div class="grid g3"><div class="kpi clickable" onclick="renderInsightV110('uniforms')"><div class="kpi-label">Pendentes</div><div class="kpi-value">${rows.filter(x=>!['entregue','cancelado'].includes(x.statusAtendimento)).length}</div><span class="kpi-arrow">›</span></div><div class="kpi orange"><div class="kpi-label">Em produção</div><div class="kpi-value">${prod}</div></div><div class="kpi green"><div class="kpi-label">Prontas para retirada</div><div class="kpi-value">${ready}</div></div></div><div class="card" style="margin-top:14px">${rows.length?`<div class="table-wrap" style="border:0"><table><thead><tr><th>Aluno</th><th>Modelo / variação</th><th>Origem</th><th>Pagamento</th><th>Atendimento</th><th style="text-align:right">Total</th><th>Ação</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.alunoNome||'-')}</strong><br><span class="muted">${esc(r.turma||'')}</span></td><td>${esc(r.produto||uniformModelByIdV120(r.modeloFardaId)?.nome||'Farda')}<br><span class="muted">${esc(r.tamanho||'-')} ${r.modelo?`· ${esc(r.modelo)}`:''} · ${r.quantidade||1} un.</span></td><td>${esc(r.solicitadoVia==='portal_responsavel'?'Meu Piaget':'Secretaria')}</td><td><span class="badge ${r.statusPagamento==='pago'?'b-green':'b-yellow'}">${esc(statusLabelV120(r.statusPagamento))}</span></td><td><span class="badge b-blue">${esc(statusLabelV120(r.statusAtendimento))}</span></td><td class="money">${fmt(r.totalCentavos)}</td><td><button class="btn btn-light" onclick="updateUniformStatus('${r.id}')">Alterar estado</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum pedido de farda.</div>'}</div>`}catch(e){console.warn('fardas-v221',e);$('#mainContent').innerHTML=pageHeader('Fardas','Não foi possível carregar os pedidos de farda.')+`<div class="alert danger">${esc(e.message||'Falha de leitura')}. <button class="btn btn-light" onclick="renderFardas()">Tentar novamente</button></div>`}}
async function newUniformOrder(){await refreshStockStateV120();const models=state.uniformModels||[];openModal('Novo pedido de farda',`<div class="fg"><label>Aluno</label><input class="fi" id="uniformStudentText" oninput="searchStudentsInto(this.value,'uniformStudentResults','chooseUniformStudent')"><input type="hidden" id="uniformStudentId"><div id="uniformStudentResults" class="search-results"></div></div><div class="fg"><label>Modelo</label><select id="manualUniformModelIdV120" class="fi" onchange="renderManualUniformFieldsV120()">${models.map(m=>`<option value="${m.id}">${esc(m.nome)}</option>`).join('')}</select></div><div id="manualUniformFieldsV120"></div>`);renderManualUniformFieldsV120()}
function renderManualUniformFieldsV120(){const m=uniformModelByIdV120($('#manualUniformModelIdV120')?.value)||(state.uniformModels||[])[0];if(!m)return;const sizes=[...(m.tamanhosInfantis||[]),...(m.tamanhosAdultos||[])];$('#manualUniformFieldsV120').innerHTML=`<div class="form-row"><div class="fg"><label>Tamanho</label><select id="uniformSize" class="fi" onchange="renderManualUniformAvailabilityV120()">${sizes.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="fg"><label>Variação</label><select id="uniformModel" class="fi" onchange="renderManualUniformAvailabilityV120()"><option value="">Modelo único</option><option value="masculino">Masculino</option><option value="feminino">Feminino</option></select></div></div><div class="form-row"><div class="fg"><label>Quantidade</label><input id="uniformQty" type="number" min="1" value="1" class="fi" oninput="renderManualUniformAvailabilityV120()"></div><div class="fg"><label>Pagamento</label><select id="uniformPayment" class="fi"><option value="pago">Pago</option><option value="aguardando_pagamento">Aguardando pagamento</option></select></div></div><div id="manualUniformAvailabilityV120"></div><button class="btn btn-primary" style="width:100%;margin-top:12px" onclick="saveUniformOrder()">Salvar pedido</button>`;renderManualUniformAvailabilityV120()}
function manualUniformInfoV120(){const m=uniformModelByIdV120($('#manualUniformModelIdV120')?.value),size=$('#uniformSize')?.value,adult=(m?.tamanhosAdultos||[]).includes(size);if($('#uniformModel')){$('#uniformModel').disabled=!adult||!m?.generoAdulto;if(!adult||!m?.generoAdulto)$('#uniformModel').value='';else if(!$('#uniformModel').value)$('#uniformModel').value='masculino'}const gender=adult&&m?.generoAdulto?($('#uniformModel')?.value||'masculino'):'';const q=Math.max(1,Number($('#uniformQty')?.value||1)),s=uniformStockDocV120(m?.id,size,gender),available=s?.configurado?stockAvailableV120(s):0,unit=adult?Number(m?.precoAdultoCentavos||4700):Number(m?.precoInfantilCentavos||4200);return{m,size,gender,q,s,available,unit,production:!s?.configurado||available<q}}
function renderManualUniformAvailabilityV120(){const h=$('#manualUniformAvailabilityV120');if(!h)return;const i=manualUniformInfoV120();h.innerHTML=`<div class="alert ${i.production?'warn':''}">${i.production?'<strong>Sem disponibilidade imediata.</strong> O pedido seguirá para produção.':`<strong>${i.available} unidade(s) disponível(is).</strong>`}<br>Preço: ${fmt(i.unit)} por unidade.</div>${!i.production?`<div class="fg" style="margin-top:12px"><label>Atendimento</label><select id="manualUniformActionV120" class="fi"><option value="reservar">Reservar para retirada</option><option value="saida_imediata">Entregar agora</option></select></div>`:''}`}
async function saveUniformOrder(){const id=$('#uniformStudentId').value;if(!id)return appMessage('Selecione o aluno.');const a=state.students.find(x=>x.id===id),i=manualUniformInfoV120(),action=i.production?'producao':($('#manualUniformActionV120')?.value||'reservar'),status=action==='producao'?'aguardando_producao':action==='reservar'?'reservado_estoque':'entregue',ref=db.collection('pedidos_farda').doc();try{await db.runTransaction(async tx=>{await applyUniformInventoryTxV120(tx,[{modeloFardaId:i.m.id,tamanho:i.size,modelo:i.gender,quantidade:i.q,statusAtendimento:status,estoqueAcao:action}],{origem:'pedido_farda_manual',sourceId:ref.id,alunoId:id});tx.set(ref,{id:ref.id,alunoId:id,alunoNome:a.nome,turma:a.turma,produto:i.m.nome,modeloFardaId:i.m.id,tamanho:i.size,modelo:i.gender,quantidade:i.q,precoUnitarioCentavos:i.unit,totalCentavos:i.unit*i.q,statusPagamento:$('#uniformPayment').value,statusAtendimento:status,estoqueAcao:action,estoqueReservado:action==='reservar',estoqueBaixado:action==='saida_imediata',criadoPor:state.user.id,criadoEm:nowIso(),atualizadoEm:nowIso()})});await audit('pedido_farda_criado',{pedidoId:ref.id,alunoId:id});await refreshStockStateV120();closeModal();renderFardas();toast('Pedido de farda salvo.')}catch(e){appMessage(e.message)}}
async function updateUniformStatus(id){const s=await db.collection('pedidos_farda').doc(id).get(),r=s.data();openModal('Alterar estado da farda',`<p><strong>${esc(r.alunoNome||'-')}</strong> — ${esc(r.tamanho||'-')} ${esc(r.modelo||'')}</p><div class="fg"><label>Estado</label><select id="newUniformStatus" class="fi">${['aguardando_pagamento','reservado_estoque','aguardando_producao','enviado_fabrica','em_producao','pronto_retirada','entregue','cancelado'].map(x=>`<option value="${x}" ${x===r.statusAtendimento?'selected':''}>${statusLabelV120(x)}</option>`).join('')}</select></div><button class="btn btn-primary" style="width:100%" onclick="saveUniformStatus('${id}')">Salvar estado</button>`)}
async function saveUniformStatus(id){const newStatus=$('#newUniformStatus').value,ref=db.collection('pedidos_farda').doc(id);try{await db.runTransaction(async tx=>{const snap=await tx.get(ref),r=snap.data();if(!r)throw new Error('Pedido não encontrado.');const sref=db.collection('estoques').doc(uniformStockIdV120(r.modeloFardaId||'camisa_padrao',r.tamanho,r.modelo||''));let stock=null;if(r.estoqueReservado&&(newStatus==='entregue'||newStatus==='cancelado')){const ss=await tx.get(sref);stock=ss.data();if(stock){const q=Number(r.quantidade||1),reserved=Math.max(0,Number(stock.quantidadeReservada||0)-q);if(newStatus==='entregue'){if(Number(stock.quantidadeFisica||0)<q)throw new Error('Estoque físico insuficiente para concluir a entrega.');tx.set(sref,{quantidadeFisica:Number(stock.quantidadeFisica||0)-q,quantidadeReservada:reserved,atualizadoEm:nowIso()},{merge:true})}else tx.set(sref,{quantidadeReservada:reserved,atualizadoEm:nowIso()},{merge:true});const mov=db.collection('movimentos_estoque').doc();tx.set(mov,{id:mov.id,produtoId:'camisa_farda',modeloFardaId:r.modeloFardaId||'camisa_padrao',variacaoKey:stock.variacaoKey,tamanho:r.tamanho,modelo:r.modelo||'',tipo:newStatus==='entregue'?'entrega_reserva':'liberacao_reserva',quantidade:newStatus==='entregue'?-q:q,origem:'pedido_farda',sourceId:id,alunoId:r.alunoId||null,usuarioId:state.user.id,dataChave:dateKey(),criadoEm:nowIso()})}}
      tx.set(ref,{statusAtendimento:newStatus,estoqueReservado:r.estoqueReservado&&(newStatus!=='entregue'&&newStatus!=='cancelado'),estoqueBaixado:r.estoqueBaixado||newStatus==='entregue',atualizadoEm:nowIso(),alteradoPor:state.user.id},{merge:true})});await audit('pedido_farda_estado',{pedidoId:id,status:newStatus});await refreshStockStateV120();closeModal();renderFardas();toast('Estado atualizado.')}catch(e){appMessage(e.message)}}

