function addToCart(id){const p=productById(id),i=productAvailabilityV120(p);if(!i.sellable)return appMessage(`${p.nome} não está disponível. ${stockStatusTextV120(i)}.`);const row=state.cart.find(x=>x.productId===id);const next=(row?.qty||0)+1;if(Number.isFinite(i.available)&&next>i.available)return appMessage(`Disponível: ${i.available}.`);if(row)row.qty++;else state.cart.push({productId:id,qty:1});renderCashCart()}

