/* Pagamento guiado: abre diretamente na forma escolhida pelo atendente. */
function openPaymentV110(method='dinheiro'){
  const rem=remainingSaleV110();if(rem<=0)return appMessage('A venda já está totalmente coberta.');
  const chosen=['dinheiro','cartao','pix'].includes(method)?method:'dinheiro';
  openModal('Adicionar pagamento',`<div class="fg"><label>Forma</label><select id="v110PayMethod" class="fi" onchange="renderPaymentFieldsV110()"><option value="dinheiro" ${chosen==='dinheiro'?'selected':''}>Dinheiro</option><option value="cartao" ${chosen==='cartao'?'selected':''}>Cartão</option><option value="pix" ${chosen==='pix'?'selected':''}>Pix</option></select></div><div class="fg"><label id="v110PayAmountLabel">Valor aplicado nesta venda</label><input id="v110PayAmount" class="fi" value="${(rem/100).toFixed(2).replace('.',',')}" inputmode="decimal" oninput="const g=document.getElementById('v110CardGross');if(g&&g.dataset.manual!=='1')g.value=this.value;const c=document.getElementById('v110CashTendered');if(c)c.value=this.value"></div><div id="v110PayFields"></div><button class="btn btn-primary" style="width:100%;margin-top:12px" onclick="confirmPaymentV110()">Adicionar pagamento</button>`);renderPaymentFieldsV110()
}

async function checkParentOrderAvailabilityV120(p,dates,qty){
  const comps=productComponents(p,qty);
  for(const c of comps){const cp=productById(c.produtoId);if(!cp)continue;const mode=productControlV120(cp);
    if(mode==='unitario'){const s=stockDocV120(cp.id);if(!s?.configurado)return{ok:false,error:`O estoque de ${cp.nome} ainda não foi configurado.`};const need=Number(c.quantidade||0)*dates.length,available=stockAvailableV120(s);if(need>available)return{ok:false,error:`O pedido precisa de ${need} unidade(s) de ${cp.nome}, mas há ${available} disponível(is).`}}
    if(mode==='capacidade_diaria'){const snaps=await Promise.all(dates.map(d=>db.collection('disponibilidade_salgados').doc(d).get()));for(let i=0;i<dates.length;i++){const doc=snaps[i].exists?snaps[i].data():{},info=typeof lunchDayStatusV181==='function'?lunchDayStatusV181(dates[i],doc):{active:true,available:Number(doc.quantidadePlanejada??state.config?.quantidadePadraoSalgados??30)},need=Number(c.quantidade||0);if(!info.active)return{ok:false,error:`Não haverá venda de lanche em ${dates[i].split('-').reverse().join('/')}.`};if(need>info.available)return{ok:false,error:`Em ${dates[i]}, há apenas ${info.available} salgado(s) disponível(is) para este pedido.`}}}
  }
  return{ok:true}
}

